begin;
-- Security-invoker views: grant only to the limited application role. No raw rows to the browser.
create view shop.published_catalogue with(security_invoker=true) as
 select p.id,p.slug,p.category,p.title,p.description,p.selling_price,p.published_at,p.is_featured,p.is_bestseller,p.fabric,p.colour,p.occasion,
 jsonb_build_object('id',p.id,'slug',p.slug,'name',p.title,'published',true,'publishedAt',p.published_at,'pricePaise',p.selling_price,'mrpPaise',p.compare_at_price,'description',p.description,'categories',jsonb_build_array(p.category),'fabric',p.fabric,'style',initcap(p.category),'colour',p.colour,'occasion',case when p.occasion='' then '[]'::jsonb else jsonb_build_array(p.occasion) end,'seoTitle',nullif(p.seo_title,''),'seoDescription',nullif(p.seo_description,''),'newArrival',p.published_at>now()-interval '30 days','bestseller',p.is_bestseller,'taxNote',case when p.details#>>'{costs,tax}'='inclusive' then 'Price includes applicable GST.' end,
 'specifications',jsonb_strip_nulls(jsonb_build_object('Pattern',nullif(p.pattern,''),'Sleeves',nullif(p.sleeve_type,''),'Neckline',nullif(p.neck_style,''),'Length',nullif(p.kurti_length,''),'Care',nullif(p.care_instructions,''),'Measurements',nullif(p.details#>>'{attrs,measurements}',''),'Details',nullif(p.details#>>'{attrs,specifications}',''))),
 'images',(select jsonb_agg(jsonb_build_object('src','/api/media/'||i.asset_id,'alt',i.alt_text) order by i.image_order) from shop.product_images i where i.product_id=p.id),
 'variants',(select jsonb_agg(jsonb_build_object('id',v.id,'size',v.size,'colour',nullif(v.colour,''),'pricePaise',v.variant_price_override,'stock',case when v.is_available then greatest(0,v.stock_quantity-coalesce((select sum(r.quantity) from shop.reservations r where r.variant_id=v.id and r.expires_at>now()),0)) else 0 end) order by v.created_at,v.id) from shop.product_variants v where v.product_id=p.id),
 'reviews',coalesce((select jsonb_agg(x.row) from(select jsonb_build_object('id',r.id,'displayName','PARADELLE customer','body',r.review_text,'rating',r.rating,'verified',true) row from shop.product_reviews r where r.product_id=p.id and r.publication_status='published' and r.verification_status='purchase' order by r.created_at desc limit 20)x),'[]'),
 'sourceReviews',coalesce((select jsonb_agg(x.row) from(select jsonb_build_object('id',r.id,'body',r.review_text,'rating',r.rating,'source',r.source,'permission','granted','approved',true) row from shop.product_reviews r where r.product_id=p.id and r.publication_status='published' and r.verification_status='licensed' order by r.created_at desc limit 10)x),'[]')) product
 from shop.products p where p.status='published';
create view shop.product_register with(security_invoker=true) as select p.id,p.revision,p.title,coalesce(p.slug,'') slug,coalesce(p.sku,'') sku,p.status,p.category,p.selling_price as "pricePaise",p.updated_at as "updatedAt",(select '/admin/media/'||asset_id from shop.product_images where product_id=p.id and is_primary) thumbnail,coalesce((select jsonb_agg(size order by size) from shop.product_variants where product_id=p.id),'[]') sizes,coalesce((select sum(stock_quantity)::int from shop.product_variants where product_id=p.id),0) stock from shop.products p;
create view shop.order_register with(security_invoker=true) as select o.id,o.customer_id,o.revision,o.order_number reference,o.customer_name_snapshot customer,o.customer_phone_snapshot mobile,o.created_at date,o.total_amount as "totalPaise",o.payment_status payment,o.fulfilment_status fulfilment,coalesce((select jsonb_agg(jsonb_build_object('id',l.id,'name',l.product_title_snapshot,'image',replace(l.product_image_snapshot,'/api/media/','/admin/media/'),'size',l.selected_size,'quantity',l.quantity,'unitPaise',l.unit_price,'sourceUrl',l.source_url_snapshot) order by l.id) from shop.order_items l where l.order_id=o.id),'[]') items from shop.orders o;
create view shop.customer_register with(security_invoker=true) as select c.id,c.full_name name,c.phone_number mobile,count(o.id)::int orders,coalesce(sum(o.total_amount-coalesce((select sum(r.amount) from shop.refunds r where r.order_id=o.id and r.status='processed'),0)),0)::bigint as "spendPaise",max(o.created_at) as "lastOrder" from shop.customers c left join shop.orders o on o.customer_id=c.id group by c.id;
create view shop.review_register with(security_invoker=true) as select r.id,r.revision,r.product_id as "productId",p.title as "productTitle",r.review_text body,r.rating,case when r.verification_status='purchase' then 'paradelle' else 'authorised-feed' end origin,r.source,'granted'::text permission,r.verification_status='purchase' as "verifiedPurchase",r.publication_status status,r.created_at at from shop.product_reviews r join shop.products p on p.id=r.product_id;
create view shop.inventory_register with(security_invoker=true) as select v.id,v.revision,p.id as "productId",p.title,coalesce(v.sku,'') sku,v.size,v.stock_quantity stock,v.low_threshold threshold,v.is_available enabled,v.updated_at as "updatedAt",sum(v.stock_quantity) over(partition by v.product_id)::int as "productStock" from shop.product_variants v join shop.products p on p.id=v.product_id;
create view shop.job_register with(security_invoker=true) as select j.id,j.revision,j.source_url as "sourceUrl",coalesce(j.draft->>'title',j.generated_content->>'title','') title,jsonb_build_object('extraction',j.extraction_status,'content',j.content_status,'images',j.image_generation_status,'reviews',j.review_import_status,'approval',j.status) stages,j.updated_at as "updatedAt",j.error_message error from shop.product_import_jobs j;
grant select on shop.published_catalogue,shop.product_register,shop.order_register,shop.customer_register,shop.review_register,shop.inventory_register,shop.job_register to paradelle_runtime;
create table shop.analytics_claims(order_id uuid not null references shop.orders,channel text not null check(channel in('ga','meta')),created_at timestamptz not null default now(),primary key(order_id,channel));alter table shop.analytics_claims enable row level security;create policy backend on shop.analytics_claims to paradelle_runtime using(true) with check(true);grant select,insert on shop.analytics_claims to paradelle_runtime;
-- Hosted deployments create a unique LOGIN and grant paradelle_runtime to that login, NEVER service_role or postgres.
commit;
